/* eslint-disable */
/**
 * GERADO por assets/personagem/gerar-arte.mjs — não edite à mão.
 *
 * Uma montagem por pose, cada uma vinda de um boneco que o artista montou
 * no Figma. Proporção, escala e posição são dele: o aceno tem um braço
 * DESENHADO erguido, não um braço girado por código. A cabeça segue a mesma
 * regra: virar de lado e ficar bravo são a mesma troca de `Rosto`.
 *
 * `caixas` recorta a peça dentro da sua fonte; `montagens` diz, por pose,
 * qual arte cada junta usa e onde ela se assenta no palco. Os pivôs e o
 * movimento por cima ficam em pose.ts e estados.ts.
 */
import type { ReactNode } from 'react';
import { Ellipse, Path } from 'react-native-svg';

/** Cada desenho, uma vez só. Variante nova leva o sufixo da pose que a estreou. */
export type Peca = 'calda' | 'perna-dir' | 'perna-esq' | 'braco-esq' | 'braco-dir' | 'tronco' | 'front' | 'braco-esq-acena' | 'calda-comemora' | 'braco-dir-comemora' | 'sideways' | 'profile' | 'backward' | 'back' | 'triste' | 'bravo' | 'surpreso' | 'sonolento' | 'piscando' | 'tronco-costas' | 'tronco-sideways';

/** O que o motor move. `cabeca` é a junta; a peça dela é o rosto. */
export type Junta = 'calda' | 'perna-dir' | 'perna-esq' | 'braco-esq' | 'braco-dir' | 'tronco' | 'cabeca';

/**
 * O desenho da cabeça inteira — para onde ela olha E que cara faz.
 * Virar de lado e ficar bravo são a mesma operação, então é um eixo só.
 */
export type Rosto = 'front' | 'sideways' | 'profile' | 'backward' | 'back' | 'triste' | 'bravo' | 'surpreso' | 'sonolento' | 'piscando';

/** Os desenhos de `cabeca`, na ordem em que entraram. O primeiro é o padrão. */
export const rostos: readonly Rosto[] = ['front', 'sideways', 'profile', 'backward', 'back', 'triste', 'bravo', 'surpreso', 'sonolento', 'piscando'];

/**
 * Para que lado o corpo está virado. Virar é do corpo todo: um `sideways`
 * com o tronco de frente lê como pescoço torcido.
 */
export type Tronco = 'tronco' | 'tronco-costas' | 'tronco-sideways';

/** Os desenhos de `tronco`, na ordem em que entraram. O primeiro é o padrão. */
export const troncos: readonly Tronco[] = ['tronco', 'tronco-costas', 'tronco-sideways'];

/** As poses que o artista montou. */
export type NomeDaMontagem = 'parado' | 'acena' | 'comemora';

/**
 * A montagem a que as outras se alinham — o chão e o eixo do boneco.
 * É também a única que tem arte para TODAS as juntas, então é dela que os
 * pivôs das variantes são herdados.
 */
export const montagemDeReferencia: NomeDaMontagem = 'parado';

/** O retângulo que as montagens ocupam. Tudo aqui vive nessas unidades. */
export const palco = { largura: 529.02, altura: 690.98 };

